void led_init(void) {
    // clock first: without it, GPIOA ignores writes
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN;
    GPIOA->MODER |= (1u << (5 * 2));
    GPIOA->BSRR  = (1u << 5);
}

